void u(char *s, int b) {
    char r[1000];
    int i = 0, j = 0;
    while (s[i]) {
        if (isspace(s[i])) {
            int p = 0;
            while (isspace(s[i])) {
                r[j++] = s[i++];
                p = 1;
            }
            if (p) {
                int t = b, n = 0, m[20];
                if (t < 0) { r[j++] = '-'; t = -t; }
                if (t == 0) r[j++] = '0';
                while (t > 0) { m[n++] = t % 10; t /= 10; }
                for (int k = n - 1; k >= 0; k--) r[j++] = '0' + m[k];
            }
        } else {
            r[j++] = s[i++];
        }
    }
    r[j] = '\0';
    strcpy(s, r);
}

